#[cfg(test)]
mod tests {
    use super::*;
    use crate::assets::tmpl::TmplAssets;
    use crate::errors::KamError;
    use std::collections::HashMap;
    use std::fs;
    use std::fs::File;
    use std::io::Write;
    use tempfile::tempdir;

    #[test]
    fn test_template_render_error_in_file() {
        let src_dir = tempdir().unwrap();
        let dst_dir = tempdir().unwrap();
        let src_path = src_dir.path().join("bad.tmpl");

        // Write a deliberately malformed template (unclosed brace) to trigger parse/render error.
        fs::write(&src_path, "{{ unclosed").unwrap();

        let vars: HashMap<String, String> = HashMap::new();
        let res = TemplateCopier::copy_and_replace_with_rules(
            src_dir.path(),
            dst_dir.path(),
            &vars,
            true,
            "test_template",
            None,
            None,
        );
        match res {
            Err(KamError::TemplateRenderError(_)) => (),
            Err(e) => panic!("expected TemplateRenderError, got {e:?}"),
            Ok(()) => panic!("expected error, got Ok"),
        }
    }

    // Filename render tests can be brittle because Tera often treats
    // brace-containing filenames as plain text or renders undefined variables
    // to empty strings. We already cover rendering error behavior in
    // `test_template_render_error_in_file` (malformed template content), which
    // exercises the same TemplateRenderError path. If filename-specific tests
    // are required in the future, add deterministic cases that reliably produce
    // a parse/render error (for example, by creating an actual malformed
    // template file and asserting the error), rather than relying on filename
    // parsing semantics which may vary across Tera versions.

    #[test]
    fn bundled_template_archives_are_complete() {
        for template in [
            "ak3_template",
            "downloader_template",
            "kam_template",
            "lsposed_template",
            "zygisk_template",
            "meta_template",
            "tmpl_template",
        ] {
            let asset = format!("{template}.tar.gz");
            let archive = TmplAssets::get(&asset).unwrap_or_else(|| panic!("missing {asset}"));
            assert!(!archive.data.is_empty(), "empty bundled archive: {asset}");
        }
    }

    #[test]
    fn bundled_injection_templates_render_payload_paths_and_keep_hooks_executable() {
        for (template, payload) in [
            ("zygisk_template", "native/jni/module.cpp"),
            (
                "lsposed_template",
                "android/app/src/main/assets/xposed_init",
            ),
        ] {
            let archive = TmplAssets::get(&format!("{template}.tar.gz")).unwrap();
            let source = tempdir().unwrap();
            let output = tempdir().unwrap();
            tar::Archive::new(flate2::read::GzDecoder::new(archive.data.as_ref()))
                .unpack(source.path())
                .unwrap();
            let vars = HashMap::from([
                ("prop.id".to_string(), "org.example.injection".to_string()),
                ("prop.name".to_string(), "Injection Example".to_string()),
            ]);
            TemplateManager::copy_and_replace(source.path(), output.path(), &vars, true, template)
                .unwrap();
            assert!(output.path().join(payload).is_file());
            assert!(
                output
                    .path()
                    .join("src/org.example.injection/customize.sh")
                    .is_file()
            );
            assert!(
                fs::read_to_string(output.path().join("README.md"))
                    .unwrap()
                    .starts_with("# Injection Example")
            );
            assert!(!output.path().join("src/{{prop.id}}").exists());
            assert_eq!(
                fs::read_to_string(
                    output.path().join(
                        "src/org.example.injection/META-INF/com/google/android/updater-script"
                    )
                )
                .unwrap()
                .trim(),
                "#MAGISK"
            );
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                let hook = fs::read_dir(output.path().join("hooks/pre-build"))
                    .unwrap()
                    .next()
                    .unwrap()
                    .unwrap();
                assert_ne!(hook.metadata().unwrap().permissions().mode() & 0o111, 0);
            }
        }
    }

    #[test]
    fn test_is_binary_detects_null_byte() {
        let tmp = tempdir().unwrap();
        let fpath = tmp.path().join("binfile");
        let mut f = File::create(&fpath).unwrap();
        f.write_all(&[0u8, 1, 2, 3]).unwrap();
        assert!(is_binary(&fpath));
    }
}
